            info_row('sh', 'Section headers', header_tuple(elf.shnum, elf.shentsize, elf.shoff, 'sh'))]
    if elf.flags:
        out.append(info_row('e_flags', 'Flags', f'0x{elf.flags:x}'))
    out.append('    </table>\n')
    return ''.join(out)


def dumps(elf):
    n = len(elf.data)
    offsets = '\n'.join(f'{i:x}' for i in range(0, n, 16))
    if n % 16 == 0:
        offsets += '\n'
    hexbytes = [f'{b:02x}' for b in range(256)]
    ascii_table = [chr(b) if 33 <= b <= 126 else '.' for b in range(256)]
    for c, esc in [('&', '&amp;'), ('<', '&lt;'), ('>', '&gt;'), ('"', '&quot;'), ("'", '&apos;')]:
        ascii_table[ord(c)] = esc
    hexdump = []
    ascii_dump = []
    starts, ends = elf.starts, elf.ends
    for i, b in enumerate(elf.data):
        if i:
            hexdump.append('\n' if i % 16 == 0 else ' ')
        if i in starts:
            for css in starts[i]:
                hexdump.append(f"<span class='{css}'>")
        hexdump.append('&nbsp;' + chr(b) if i in (1, 2, 3) else hexbytes[b])
        if i in ends:
            hexdump.append('</span>' * ends[i])
        ascii_dump.append(ascii_table[b])
        if i % 16 == 15:
            ascii_dump.append('\n')
    return (f"    <div id='offsets'>{offsets}</div>\n"
            f"    <div id='bytes'>{''.join(hexdump)}</div>\n"
            f"    <div id='ascii'>{''.join(ascii_dump)}</div>\n")


def program_header_table(i, p):
    flags = ''.join(c for bit, c in ((4, 'R'), (2, 'W'), (1, 'X')) if p.flags & bit)
    return ''.join([table_start('phdr', i),
                    row('Type', label(PROGRAM_TYPE, p.type)), row('Flags', flags),
                    row('Offset in file', hex_number(p.offset)),
                    row('Size in file', dec_number(p.filesz)),
                    row('Vaddr in memory', hex_number(p.vaddr)),
                    row('Size in memory', dec_number(p.memsz)),
                    row('Alignment', hex_number(p.align)), TABLE_END])


def section_header_table(elf, i, s):
    flags = ''.join(c for bit, c in ((1, 'W'), (2, 'A'), (4, 'X')) if s.flags & bit) or '0'
    return ''.join([table_start('shdr', i), row('Index', i),
                    row('Name', elf.section_name(s)), row('Type', label(SECTION_TYPE, s.type)),
                    row('Flags', flags), row('Vaddr in memory', hex_number(s.addr)),
                    row('Offset in file', hex_number(s.offset)),
                    row('Size in file', dec_number(s.size)), row('Linked section', s.link),
                    row('Extra info', dec_number(s.info)), row('Alignment', hex_number(s.addralign)),
                    row('Size of entries', dec_number(s.entsize)), TABLE_END])


def segment_table(elf, i, p):
    out = [table_start('segment', i), row('Type', label(PROGRAM_TYPE, p.type)),
           row('Size in file', dec_number(p.filesz)), row('Size in memory', dec_number(p.memsz))]
    if p.type == 3:
        text = checked_slice(elf.data, p.offset, (p.offset + p.filesz - 1) & U64,
                             'src/report_gen.rs:266:30')
        out += [BREAK_ROW, row('Interpreter', byte_description(text))]
    elif p.type == 4:
        out.append(BREAK_ROW)
        for k, note in enumerate(elf.notes):
            if k:
                out.append('            <tr> <td><br></td> </tr>\n')
            out += [row('Name', byte_description(note.name)), row('Type', f'0x{note.type:x}')]
            if note.type == 3:
                out.append(row('Build ID', note.desc.hex()))
            else:
                out.append(row('Desc', byte_description(note.desc)))
    out.append(TABLE_END)
    return ''.join(out)


def section_table(elf, i, s):
    out = [table_start('section', i), row('Type', label(SECTION_TYPE, s.type)),
           row('Size', dec_number(s.size))]
    if s.type == 3:
        out += [BREAK_ROW, '            <tr>\n', '              <td></td>\n',
                '              <td>\n', '                <div>\n']
        for text in elf.strings.get(i, []):
            out.append(f'                  {text}\n')
        out += ['                </div>\n', '              </td>\n', '            </tr>\n']
    out.append(TABLE_END)
    return ''.join(out)


def info_tables(elf):
    out = ["    <table id='sticky_table' cellspacing='0'>\n", '      <tr>\n',
           "        <td id='desc'></td>\n", "        <td class='infotables'>\n"]
    for i, p in enumerate(elf.programs):
        out.append(program_header_table(i, p))
    for i, s in enumerate(elf.sections):
        out.append(section_header_table(elf, i, s))
    out += ['        </td>\n', "        <td class='infotables'>\n"]
    for i, p in enumerate(elf.programs):
        out.append(segment_table(elf, i, p))
    for i, s in enumerate(elf.sections):
        out.append(section_table(elf, i, s))
    out += ['        </td>\n', '      </tr>\n', '    </table>\n']
    return ''.join(out)


def render(elf, filename, title):
    templates = files('elfreport')
    prefix = templates.joinpath('prefix.template').read_text(encoding='utf-8')
    suffix = templates.joinpath('suffix.template').read_text(encoding='utf-8')
    connections = []
    for i in range(len(elf.programs)):
        connections.append(f"      connect('.bin_phdr{i} > .p_offset', '.bin_segment{i}');\n")
    for i in range(len(elf.sections)):
        connections.append(f"      connect('.bin_shdr{i} > .sh_offset', '.bin_section{i}');\n")
    suffix = suffix.replace('@@FILELEN@@', str(len(elf.data))).replace('@@CONNECTIONS@@', ''.join(connections))
    return ''.join([prefix.replace('@@TITLE@@', title), header_table(elf, filename),
                    dumps(elf), info_tables(elf), suffix])
